        return 0 <= x < n and 0 <= y < n

    def count_free_cells():
        return sum(row.count('.') for row in board)

    def dfs(x, y, pieces_left):
        if pieces_left == 0:
            return True
        if not is_valid(x, y) or board[x][y] == '#':
            return False

        # Try placing a piece
        piece_positions = [
            (0, 0), (0, 1), (0, 2), (1, 1), (2, 1)
        ]

        # Check if we can place the piece
        can_place = True
        for dx, dy in piece_positions:
            nx, ny = x + dx, y + dy
            if not is_valid(nx, ny) or board[nx][ny] == '#':
                can_place = False
                break

        if can_place:
            # Place the piece
            for dx, dy in piece_positions:
                nx, ny = x + dx, y + dy
                board[nx][ny] = '#'

            # Try to place the next piece
            for nx in range(n):
                for ny in range(n):
                    if board[nx][ny] == '.':
                        if dfs(nx, ny, pieces_left - 1):
                            return True

            # If placing the next piece fails, remove the current piece
            for dx, dy in piece_positions:
                nx, ny = x + dx, y + dy
                board[nx][ny] = '.'

        # Try the next cell
        for nx in range(n):
            for ny in range(n):
                if board[nx][ny] == '.':
                    if dfs(nx, ny, pieces_left):
                        return True

        return False

    free_cells = count_free_cells()
    if free_cells % 5 != 0:
        return "NO"

    pieces_needed = free_cells // 5
    for i in range(n):
        for j in range(n):
