def can_tile_board(n, board):
    from collections import deque

    def is_valid(x, y):
        return 0 <= x < n and 0 <= y < n

    def bfs(start_x, start_y):
        queue = deque([(start_x, start_y)])
        visited = set([(start_x, start_y)])
        shape = [(0, 0)]
        while queue:
            x, y = queue.popleft()
            for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nx, ny = x + dx, y + dy
                if is_valid(nx, ny) and board[nx][ny] == '.' and (nx, ny) not in visited:
                    visited.add((nx, ny))
                    queue.append((nx, ny))
                    shape.append((nx - start_x, ny - start_y))
        return shape

    def normalize_shape(shape):
        min_x = min(x for x, y in shape)
        min_y = min(y for x, y in shape)
        return sorted((x - min_x, y - min_y) for x, y in shape)

    shapes = []
    visited_global = set()

    for i in range(n):
        for j in range(n):
            if board[i][j] == '.' and (i, j) not in visited_global:
                shape = bfs(i, j)
                normalized_shape = normalize_shape(shape)
                if normalized_shape not in shapes:
                    shapes.append(normalized_shape)
                visited_global.update((i + x, j + y) for x, y in shape)

    # Check if the shapes can form a complete board
    piece_shape = [(0, 0), (0, 1), (1, 0), (1, 1), (1, 2)]
    piece_shape = normalize_shape(piece_shape)

    def can_form_board(shapes, piece_shape, n):
        board = [[False] * n for _ in range(n)]
        for shape in shapes:
            for x, y in shape:
                for px, py in piece_shape:
                    nx, ny = x + px, y + py
                    if not is_valid(nx, ny) or board[nx][ny]:
                        return False
                    board[nx][ny] = True
        return all(all(row) for row in board)

    return "YES" if can_form_board(shapes, piece_shape, n) else "NO"

